import hmac
import hashlib
import struct
import time
import os
from typing import Optional, Tuple

# Token format: version(1) | timestamp(8) | user_id(4) | permissions(4) | payload(N) | signature(32)

SECRET_KEY = os.environ.get('TOKEN_SECRET', '').encode('utf-8')
MAX_TOKEN_AGE = int(os.environ.get('MAX_TOKEN_AGE', '3600'))
MAX_CLOCK_SKEW = int(os.environ.get('MAX_CLOCK_SKEW', '300'))

class TokenError(Exception):
    pass

class SecureTokenValidator:
    """Validates authentication tokens with timing-safe comparison and replay protection."""

    def __init__(self, secret: bytes, max_age: int = 3600, max_skew: int = 300):
        if not secret or len(secret) < 16:
            raise ValueError("Secret key must be at least 16 bytes")
        self.secret = secret
        self.max_age = max_age
        self.max_skew = max_skew
        self._seen_nonces = set()

    def _compute_signature(self, data: bytes) -> bytes:
        """Compute HMAC-SHA256 signature over token data."""
        return hmac.new(self.secret, data, hashlib.sha256).digest()

    def _constant_time_compare(self, a: bytes, b: bytes) -> bool:
        """Timing-safe comparison of two byte strings."""
        return hmac.compare_digest(a, b)

    def _validate_timestamp(self, token_time: int) -> bool:
        """Check token timestamp is within acceptable bounds."""
        current_time = int(time.time())
        # Calculate age using 32-bit arithmetic to match token format
        age = (current_time - token_time) & 0xFFFFFFFF
        return age <= self.max_age + self.max_skew

    def _extract_permissions(self, perm_bits: int) -> dict:
        """Extract permission flags from 32-bit permission field."""
        return {
            'read': bool(perm_bits & 0x01),
            'write': bool(perm_bits & 0x02),
            'admin': bool(perm_bits & 0x04),
            'super_admin': bool(perm_bits & 0x08),
        }

    def validate_token(self, token_bytes: bytes) -> Tuple[int, dict, bytes]:
        """Validate token and return (user_id, permissions, payload).

        Performs:
        1. Length validation
        2. Version check
        3. Signature verification (timing-safe)
        4. Timestamp freshness check
        5. Replay detection

        Returns tuple of (user_id, permissions_dict, payload_bytes)
        Raises TokenError on any validation failure.
        """
        # Minimum: version(1) + timestamp(8) + user_id(4) + perms(4) + sig(32) = 49
        if len(token_bytes) < 49:
            raise TokenError("Token too short")

        # Extract components
        version = token_bytes[0]
        if version != 0x01:
            raise TokenError(f"Unsupported token version: {version}")

        timestamp_bytes = token_bytes[1:9]
        user_id_bytes = token_bytes[9:13]
        perm_bytes = token_bytes[13:17]
        payload = token_bytes[17:-32]
        provided_sig = token_bytes[-32:]

        # Verify signature over everything except the signature itself
        data_to_verify = token_bytes[:-32]
        expected_sig = self._compute_signature(data_to_verify)

        if not self._constant_time_compare(expected_sig, provided_sig):
            raise TokenError("Invalid signature")

        # Parse fields
        token_time = struct.unpack('>Q', timestamp_bytes)[0]
        user_id = struct.unpack('>I', user_id_bytes)[0]
        perm_bits = struct.unpack('>I', perm_bytes)[0]

        # Validate timestamp
        if not self._validate_timestamp(token_time):
            raise TokenError("Token expired or clock skew too large")

        # Replay detection using first 16 bytes as nonce
        nonce = token_bytes[:17]  # version + timestamp + user_id + partial perms
        if nonce in self._seen_nonces:
            raise TokenError("Token replay detected")
        self._seen_nonces.add(nonce)

        # Prune old nonces periodically
        if len(self._seen_nonces) > 100000:
            self._seen_nonces.clear()

        permissions = self._extract_permissions(perm_bits)
        return user_id, permissions, payload


class AuthorizationGate:
    """Gates access to resources based on validated token permissions."""

    def __init__(self, validator: SecureTokenValidator):
        self.validator = validator

    def check_access(self, token_bytes: bytes, required_permission: str) -> Tuple[bool, int]:
        """Check if token grants the required permission.

        Returns (authorized: bool, user_id: int)
        """
        try:
            user_id, permissions, _ = self.validator.validate_token(token_bytes)
        except TokenError:
            return False, 0

        if required_permission not in permissions:
            return False, 0

        return permissions[required_permission], user_id

    def get_admin_context(self, token_bytes: bytes) -> Optional[dict]:
        """Get admin context if token has admin privileges."""
        try:
            user_id, permissions, payload = self.validator.validate_token(token_bytes)
        except TokenError:
            return None

        if not permissions.get('admin'):
            return None

        return {
            'user_id': user_id,
            'permissions': permissions,
            'payload': payload,
            'is_super': permissions.get('super_admin', False)
        }


def create_validator() -> SecureTokenValidator:
    """Factory function to create validator from environment."""
    secret = SECRET_KEY
    if not secret:
        raise RuntimeError("TOKEN_SECRET environment variable not set")
    return SecureTokenValidator(secret, MAX_TOKEN_AGE, MAX_CLOCK_SKEW)


def handle_request(token_hex: str, action: str) -> dict:
    """Main request handler that validates token and authorizes action."""
    try:
        token_bytes = bytes.fromhex(token_hex)
    except (ValueError, TypeError):
        return {'error': 'Invalid token encoding', 'status': 401}

    validator = create_validator()
    gate = AuthorizationGate(validator)

    permission_map = {
        'read': 'read',
        'write': 'write',
        'delete': 'admin',
        'configure': 'super_admin',
    }

    required = permission_map.get(action)
    if not required:
        return {'error': 'Unknown action', 'status': 400}

    authorized, user_id = gate.check_access(token_bytes, required)

    if not authorized:
        return {'error': 'Access denied', 'status': 403}

    return {'user_id': user_id, 'action': action, 'status': 200}
